import os,re,json
d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n')
G={}
for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
    k,h,w=m[1],int(m[2]),int(m[3])
    rows=[r.split() for r in t[m.end():].split('\n')[:h]]
    if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
        G[k]=[[int(x) for x in r] for r in rows]
print(sorted(G))
import numpy as np
for k in G: print(k, np.array(G[k]).shape)
def show(a):
    for r in a[2:11]: print(''.join(str(x) for x in r[3:12]))
show(np.array(G['Demo pair 2 output'])); print()
show(np.array(G['Demo pair 2 input']))

import numpy as np, json
def transform(g):
    a=np.array(g); h,w=a.shape
    rs=[(r,c) for r in range(h) for c in range(w) if a[r,c]==3]
    r0,r1=min(r for r,c in rs),max(r for r,c in rs)
    c0,c1=min(c for r,c in rs),max(c for r,c in rs)
    seeds=[(r,c) for r in range(r0+1,r1) for c in range(c0+1,c1) if a[r,c]==3]
    out=a.copy()
    for r in range(r0+1,r1):
        for c in range(c0+1,c1):
            if a[r,c]==3: continue
            d=min(max(abs(r-sr),abs(c-sc)) for sr,sc in seeds)
            out[r,c]= 4 if d%2==1 else 2
    return out.tolist()
for k in ['Demo pair 1','Demo pair 2']:
    print(k, transform(G[k+' input'])==G[k+' output'])
res=transform(G['Test input'])
for r in res[2:11]: print(''.join(map(str,r[3:12])))
print(json.dumps(res))
